(* [comment removed for export] *)
Definition trc_cells (m : mem) (tb : list word) : Prop :=
  rw_cells asegs m (B + 40) [C8 (Z_to_bv 64 (B + 40 + 16)); C8 (Z_to_bv 64 (Z.of_nat (length tr)))]
  /\ u64arr asegs m (B + 40 + 16) (wr_trace tr tb) /\ length tb = 255%nat.
(* [comment removed for export] *)
Definition af_cells (m : mem) (j0 : list byte) : Prop :=
  alloc_frame0 m (B + -144) (Z_to_bv 64 0x468c8) s0A s1A s2A s3A s4A s5A s6A s7A s8A s9A s10A s11A
  /\ rw_cells asegs m (B + -144) [CB 8 j0].

